$ErrorActionPreference='Stop';$Run='C:\Users\aaron\Desktop\URAP\artifacts\detached_tvd_detector_hard_finetune_v133';$PidValue=[int](Get-Content (Join-Path $Run 'pid.txt') -Raw).Trim();$Proc=Get-CimInstance Win32_Process -Filter "ProcessId=$PidValue" -ErrorAction SilentlyContinue;$Meta=Get-Content (Join-Path $Run 'start_meta.json') -Raw|ConvertFrom-Json;$LogFiles=@($Meta.stdout,$Meta.stderr)|Where-Object{Test-Path $_};$Latest=$LogFiles|Get-Item|Sort-Object LastWriteTime -Descending|Select-Object -First 1;$Text=($LogFiles|ForEach-Object{Get-Content $_ -Raw -ErrorAction SilentlyContinue}) -join "`n";$Matches=[regex]::Matches($Text,'(?m)(\d+)\/14\s+');$Epoch=if($Matches.Count){[int]$Matches[$Matches.Count-1].Groups[1].Value+1}else{0};$Gpu=& nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total --format=csv,noheader,nounits;Write-Output "STATUS=$(if($Proc){'RUNNING'}else{'NOT RUNNING'})";Write-Output "DONE_TOTAL=$Epoch/3";Write-Output "PID=$PidValue START=$($Meta.start_time)";if($Proc){Write-Output "COMMAND=$($Proc.CommandLine)"};if($Latest){Write-Output "LAST_OUTPUT=$($Latest.LastWriteTime.ToString('o')) FILE=$($Latest.FullName)"};Write-Output "GPU=$Gpu";Write-Output "STDOUT=$($Meta.stdout)";Write-Output "STDERR=$($Meta.stderr)";Get-Content $Meta.stdout -Tail 12 -ErrorAction SilentlyContinue;Get-Content $Meta.stderr -Tail 20 -ErrorAction SilentlyContinue



